create schema auth; create schema storage;
create role authenticated nologin; create role service_role nologin bypassrls;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create table storage.buckets(id text primary key, name text, public boolean, file_size_limit bigint);
create table storage.objects(id uuid default gen_random_uuid(), bucket_id text, name text);
create function storage.foldername(name text) returns text[] language sql as $$ select string_to_array(name,'/') $$;
create table public.profiles(id uuid primary key references auth.users(id), full_name text, role text, school_id uuid);
create table public.academic_years(id uuid primary key default gen_random_uuid(), name text, school_id uuid);
create table public.academic_semesters(id uuid primary key default gen_random_uuid(), academic_year_id uuid, name text, school_id uuid);
create function public.get_user_role(_u uuid) returns text language sql security definer as $$ select role from public.profiles where id=_u $$;
create table public.courses(id uuid primary key default gen_random_uuid(), school_id uuid not null, title text not null, description text, subject text, class_level text, status text default 'draft', mentor_id uuid references public.profiles(id), created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.course_modules(id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id) on delete cascade, title text not null, description text, content_url text, content_body text, vark_type text, order_index int default 0, created_at timestamptz default now());
create table public.course_topics(id uuid primary key default gen_random_uuid(), module_id uuid not null references public.course_modules(id) on delete cascade, title text not null, topic_type text not null default 'learn', content_body text, content_url text, order_index int not null default 0, created_at timestamptz not null default now());
create table public.student_topic_progress(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id), topic_id uuid not null references public.course_topics(id) on delete cascade, completed boolean not null default false, completed_at timestamptz, unique(student_id, topic_id));
create table public.student_module_progress(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id), module_id uuid not null references public.course_modules(id) on delete cascade, completed boolean default false, completed_at timestamptz, unique(student_id,module_id));
create table public.student_course_progress(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id), course_id uuid not null references public.courses(id) on delete cascade, status text default 'in_progress', progress_percent int default 0, score numeric, started_at timestamptz, completed_at timestamptz, updated_at timestamptz default now(), unique(student_id,course_id));
alter table public.courses enable row level security; alter table public.course_modules enable row level security;
alter table public.course_topics enable row level security; alter table public.student_topic_progress enable row level security;
alter table public.student_module_progress enable row level security; alter table public.student_course_progress enable row level security;
-- legacy policies approximating live DB
create policy legacy_courses_pub on public.courses for select using (status='published' and school_id=(select school_id from profiles where id=auth.uid()));
create policy "students_view_topics" on public.course_topics for select using (exists (select 1 from course_modules cm join courses c on c.id=cm.course_id where cm.id=course_topics.module_id and c.status='published'));
create policy "staff_manage_topics" on public.course_topics for all using (get_user_role(auth.uid()) in ('teacher','admin','principal'));
create policy legacy_stp_own on public.student_topic_progress for all using (student_id=auth.uid()) with check (student_id=auth.uid());
create policy legacy_smp_own on public.student_module_progress for all using (student_id=auth.uid()) with check (student_id=auth.uid());
create policy legacy_scp_own on public.student_course_progress for all using (student_id=auth.uid()) with check (student_id=auth.uid());
create policy legacy_mod_sel on public.course_modules for select using (true);
grant usage on schema public, auth, storage to authenticated, service_role;
grant all on all tables in schema public to authenticated, service_role;
grant all on all tables in schema storage to authenticated, service_role;
grant execute on all functions in schema public to authenticated, service_role;
grant execute on function auth.uid() to authenticated, service_role;
grant execute on function storage.foldername(text) to authenticated, service_role;
